package com.primehr.operations.infrastructure;
import jakarta.persistence.EntityManager;import org.springframework.stereotype.Repository;import java.time.LocalDate;import java.time.ZoneId;import java.util.*;
@Repository public class StoredDocumentCatalog {private static final List<String> ENTITIES=List.of("EvidenceArtifact","SuccessionCandidateEvidence","PerformanceMonitoringEvidence","PerformanceAppealEvidence","RrNominationEvidence","ApplicationDocumentSnapshot","ApplicantDocument","LdCompletionEvidence","EvaluationEvidence");private final EntityManager entityManager;public StoredDocumentCatalog(EntityManager e){entityManager=e;}
 public List<DocumentReference> documents(String agency){List<DocumentReference> out=new ArrayList<>();for(String entity:ENTITIES){List<Object[]> rows=entityManager.createQuery("select e.id,e.storageObjectKey,e.byteSize from "+entity+" e where e.agencyId=:agency and e.storageObjectKey is not null",Object[].class).setParameter("agency",agency).getResultList();for(Object[] row:rows)out.add(new DocumentReference(entity.toUpperCase(Locale.ROOT),(String)row[0],(String)row[1],((Number)row[2]).longValue()));}return List.copyOf(out);}
 public List<RetentionReference> retentionRecords(String agency){List<RetentionReference> out=new ArrayList<>();rows(agency,"EvidenceArtifact","e.retentionTag","e.evidenceDate",out);rows(agency,"SuccessionCandidateEvidence","e.retentionTag","e.uploadedAt",out);rows(agency,"EvaluationEvidence","e.retentionTag","e.uploadedAt",out);return List.copyOf(out);}
 private void rows(String agency,String entity,String tag,String date,List<RetentionReference> out){var values=entityManager.createQuery("select e.id,"+tag+","+date+" from "+entity+" e where e.agencyId=:agency and e.storageObjectKey is not null",Object[].class).setParameter("agency",agency).getResultList();for(Object[] row:values){LocalDate recordDate=row[2] instanceof LocalDate d?d:((java.time.Instant)row[2]).atZone(ZoneId.of("Asia/Manila")).toLocalDate();out.add(new RetentionReference(entity.toUpperCase(Locale.ROOT),(String)row[0],(String)row[1],recordDate));}}
 public record DocumentReference(String recordType,String recordId,String objectKey,long byteSize){}public record RetentionReference(String recordType,String recordId,String retentionTag,LocalDate recordDate){}
}
